<div class="reactions" id="<%= dom_id(comment, :reactions) %>" data-controller="reaction-form">
  <div class="reactions__list" id="<%= dom_id(comment, :reactions_list) %>">
    <%= render partial: "cards/comments/reactions/reaction", collection: comment.reactions.chronologically, as: :reaction, locals: { comment: comment } %>
  </div>

  <% if Current.user %>
    <button type="button"
            class="reactions__trigger btn btn--circle"
            data-reaction-form-target="trigger"
            data-action="click->reaction-form#open"
            aria-label="React to comment">
      <%= image_tag "boost-color.svg", aria: { hidden: "true" } %>
      <span class="for-screen-reader">React to comment</span>
    </button>

    <%= form_with model: [ comment.card, comment, Reaction.new ],
          class: "reaction__form",
          html: {
            hidden: true,
            data: {
              reaction_form_target: "form",
              action: "submit->reaction-form#submit turbo:submit-end->reaction-form#submitEnd keydown.esc->reaction-form#cancel click@document->reaction-form#closeOnClickOutside"
            }
          } do |form| %>
      <label class="reaction__form-label flex align-center">
        <%= form.text_field :content,
              class: "input reaction__input",
              maxlength: 16,
              required: true,
              autocomplete: "off",
              data: { reaction_form_target: "input" },
              aria: { label: "Reaction" } %>
      </label>

      <button type="submit" class="reaction__submit-btn btn btn--circle borderless" aria-label="Confirm">
        <%= icon_tag "check" %>
      </button>

      <button type="button" class="reaction__cancel-btn btn btn--circle borderless" data-action="click->reaction-form#cancel" aria-label="Cancel">
        <%= icon_tag "close" %>
      </button>
    <% end %>
  <% end %>
</div>
EOF

